if (!SL.mhOncelik) SL.mhOncelik = { t: 'Talepler', c: 'Oncelik', label: 'Öncelik', vals: vlist('Talepler', 'Oncelik', ['Yüksek', 'Orta', 'Düşük']), def: [] };
