if (!SL.pjDurum) SL.pjDurum = { t: 'Projeler', c: 'Durum', label: 'Proje durumu', vals: vlist('Projeler', 'Durum', ['Planlandı', 'Devam', 'Gecikmede', 'Riskli', 'Tamamlandı']), def: [] };

/* ═══════════════════════ 1. PAZARLAMA VE KANAL PERFORMANSI ═══════════════════════ */
