/* ═══════════════════════ 3. SATIN ALMA VE TEDARİKÇİ KALİTESİ ═══════════════════════ */
const EXT = {
  'Satın Alma GY': 'CALCULATE([Satın Alma Tutarı], SAMEPERIODLASTYEAR(Tarih[Tarih]))',
  'Zamanında GY': 'CALCULATE([Tedarikte Zamanında %], SAMEPERIODLASTYEAR(Tarih[Tarih]))',
  'Fiyat Endeksi': 'DIVIDE([Satın Alma Tutarı], SUMX(SatinAlmalar, SatinAlmalar[Adet] * RELATED(Urunler[BirimMaliyet])))',
  'Söz Verilen Gün': 'AVERAGEX(SatinAlmalar, RELATED(Tedarikciler[SozGun]))',
  'Ortalama Gecikme (gün)': 'AVERAGEX(SatinAlmalar, SatinAlmalar[TeslimGun] - RELATED(Tedarikciler[SozGun]))',
  'Geciken Sipariş': 'CALCULATE(COUNTROWS(SatinAlmalar), SatinAlmalar[Zamaninda] = "Hayır")',
  'Satın Alma Siparişi': 'COUNTROWS(SatinAlmalar)',
  'Aktif Tedarikçi': 'DISTINCTCOUNT(SatinAlmalar[TedarikciNo])',
  'Kusurlu Adet': 'SUM(SatinAlmalar[Kusurlu])',
  'Kusur Maliyeti': 'SUMX(SatinAlmalar, SatinAlmalar[Kusurlu] * SatinAlmalar[BirimFiyat])',
  'Skor: Zamanında': '45 * [Tedarikte Zamanında %]',
  'Skor: Kalite': 'VAR K = [Kusur Oranı %] RETURN IF(NOT ISBLANK(K), 35 * IF(K >= 0.1, 0, 1 - K / 0.1))',
  'Skor: Fiyat': 'VAR F = [Fiyat Endeksi] RETURN IF(NOT ISBLANK(F), 20 * IF(F <= 0.95, 1, IF(F >= 1.1, 0, (1.1 - F) / 0.15)))',
  'Tedarikçi Skoru': 'IF(NOT ISBLANK([Tedarikte Zamanında %]), [Skor: Zamanında] + [Skor: Kalite] + [Skor: Fiyat])',
  'Teslim Gün': 'MAX(SatinAlmalar[TeslimGun])', 'Söz Gün': 'MAX(Tedarikciler[SozGun])'
};
